import { describe, it, expect, vi, beforeEach } from "vitest";

// Mock the generic `bsc` bridge (mirrors graphBridge.test.ts): the read routes through `bscJson`, the
// writes through `bscWrite`/`bscRun`.
const bscJson = vi.fn();
const bscWrite = vi.fn();
const bscRun = vi.fn();
vi.mock("@/shared/lib/core/bsc", () => ({
  bscJson: (...a: unknown[]) => bscJson(...a),
  bscWrite: (...a: unknown[]) => bscWrite(...a),
  bscRun: (...a: unknown[]) => bscRun(...a),
}));

import { listDbProjects, addDbProject, removeDbProject, setDbProjectState } from "@/features/planner/list/projectsDbBridge";

describe("projectsDbBridge.listDbProjects (#2995)", () => {
  beforeEach(() => { bscJson.mockReset(); bscWrite.mockReset(); bscRun.mockReset(); });

  it("parses a valid `bsc project db list` array and shape-gates each row", async () => {
    bscJson.mockResolvedValue([
      { key: "my-app", title: "My App", pitch: "p", blueprint: "default", category: "greenfield", state: "drafted", createdAt: 1, updatedAt: 2 },
      { key: "", title: "no key" }, // dropped — empty key
      { title: "keyless" },         // dropped — no key
      { key: "no-state", title: "x" }, // dropped — no state
    ]);
    const rows = await listDbProjects();
    expect(rows).not.toBeNull();
    expect(rows).toHaveLength(1);
    expect(rows![0]).toMatchObject({ key: "my-app", title: "My App", state: "drafted", blueprint: "default", category: "greenfield" });
    expect(bscJson).toHaveBeenCalledWith(null, ["project", "db", "list", "--json"], null);
  });

  it("coerces null blueprint/category and missing numeric fields to safe defaults", async () => {
    bscJson.mockResolvedValue([{ key: "k", title: "T", state: "planning", blueprint: null, category: null }]);
    const rows = await listDbProjects();
    expect(rows![0]).toMatchObject({ key: "k", pitch: "", blueprint: null, category: null, createdAt: 0, updatedAt: 0 });
  });

  it("returns null when the payload isn't an array (degraded → keep the cache)", async () => {
    bscJson.mockResolvedValue({ nope: true });
    expect(await listDbProjects()).toBeNull();
  });

  it("returns null when the bridge yields null (unreachable / old bsc without the verb)", async () => {
    bscJson.mockResolvedValue(null);
    expect(await listDbProjects()).toBeNull();
  });

  it("returns null when the bridge throws", async () => {
    bscJson.mockRejectedValue(new Error("no bridge"));
    expect(await listDbProjects()).toBeNull();
  });
});

describe("projectsDbBridge write helpers (#2995)", () => {
  beforeEach(() => { bscJson.mockReset(); bscWrite.mockReset(); bscRun.mockReset(); });

  it("add sends the JSON object on stdin via `bsc project db add`", async () => {
    const p = { key: "k", title: "T", pitch: "p", blueprint: "default", category: "greenfield", state: "drafted" };
    await addDbProject(p);
    expect(bscWrite).toHaveBeenCalledWith(null, ["project", "db", "add"], p);
  });

  it("remove + state fire the positional verbs", async () => {
    await removeDbProject("k");
    expect(bscRun).toHaveBeenCalledWith(null, ["project", "db", "remove", "k"]);
    await setDbProjectState("k", "published");
    expect(bscRun).toHaveBeenCalledWith(null, ["project", "db", "state", "k", "published"]);
  });
});

// Launching a project records its TRIAGED marker DURABLY (#the-triaged-marker-is-never-written-through).
//
// Glance draws only triaged projects (`filterTriaged`, #2541). Both launch paths stamped the marker
// inline in their zustand `set` — and `triagedProjects` is deliberately NOT persisted, because it
// hydrates from projects.db (#4088). So the stamp lived for the session and every boot read an empty
// map from a database nothing ever wrote: the graph was blank after every restart, hiding projects
// that had in fact been worked. Measured on the real store: `bsc project db triaged` returned 0
// across 27 projects.
//
// `markProjectTriaged` did exactly the right thing and had NO production caller; `setDbTriaged` was
// not even imported in the slice that launches fleets. The assertion that matters is therefore about
// the WRITE-THROUGH, not about the in-memory map — an in-memory-only stamp is what the bug was.
import { describe, it, expect, vi, beforeEach } from "vitest";

const dbWrites: string[] = [];
vi.mock("@/features/planner/list/projectsDbBridge", async (importOriginal) => {
  const real = await importOriginal<typeof import("@/features/planner/list/projectsDbBridge")>();
  return { ...real, setDbTriaged: async (key: string) => { dbWrites.push(key); } };
});

const { useAppStore } = await import("@/store");

beforeEach(() => {
  dbWrites.length = 0;
  useAppStore.setState({ tabs: [], triagedProjects: {}, automations: [] });
});

describe("a launched project is recorded as triaged in the durable store", () => {
  it("writes the marker through when a fleet (or a lone director) launches", () => {
    // The architect's handoff takes this path: `bsc fleet director new` builds a director-only
    // FleetPlan and hands it to `fleetStartProject`, so this is what makes its project appear.
    useAppStore.getState().fleetStartProject(
      "Pain Point Finder",
      { recommended: 0, reasoning: "director only", streams: [], director: { enabled: true } },
      "pain-point-finder",
    );
    expect(dbWrites, "the marker must reach projects.db, not just the store").toContain("pain-point-finder");
    expect(useAppStore.getState().triagedProjects["pain-point-finder"]).toBeTruthy();
  });

  it("writes it through when triage launches", () => {
    useAppStore.getState().triageStartProject("Pain Point Finder", ["repo-a"], "pain-point-finder");
    expect(dbWrites).toContain("pain-point-finder");
  });

  it("records NOTHING when triage no-ops for want of a repo", () => {
    // The updater bails on an empty repo list, so no tab is created and nothing was worked — marking
    // it would put a project on the graph that never launched.
    useAppStore.getState().triageStartProject("Pain Point Finder", [], "pain-point-finder");
    expect(dbWrites).toEqual([]);
  });
});
